colourBodies.metal:
float value=clamp(dot(m,channels),0.0,1.0);
float coverage;
if(range.y>range.x) coverage=smoothstep(range.x,range.y,value);
else coverage=step(range.x,value);
if(invert>0.5) coverage=1.0-coverage;
return float4(c.rgb,c.a*coverage);

